local addonName, ns = ...

ns.VERSION = "0.1.0"
-- Field Guide's logo, shipped in the addon (Media\make_icon.py draws it).
ns.ICON = "Interface\\AddOns\\FieldGuide\\Media\\Icon"

function ns.IconMarkup(size)
    return ("|T%s:%d:%d|t"):format(ns.ICON, size, size)
end

ns.PREFIX = ns.IconMarkup(14) .. " |cff8fd16aField Guide|r"

-- Filled by Guides\*.lua (generated by tools/FieldGuide/build_guides.py).
ns.Guides = {}
ns.Quests = {}

ns.DEFAULTS = {
    shown = true,
    locked = false,
    nextSteps = 4,      -- upcoming steps listed under the current one
    focusQuestie = true, -- focus the current quest in Questie's tracker
    window = { point = "RIGHT", x = -40, y = 60 },
    dock = true,        -- sit under Waypoint's arrow (when Waypoint is installed)
    manageTracking = true, -- track the guide's quests, untrack the rest (never the ones you tracked)
    wingMaps = {},      -- [uiMapID inside a dungeon] = the wing it belongs to, learned as you play
}

ns.CHAR_DEFAULTS = {
    minimap = { angle = 160, hide = false },
    guide = nil,     -- a guide key you picked; nil: your race's guide
    section = nil,   -- a section id you picked; nil: the next one worth doing
    skipped = {},    -- step keys you skipped by hand
    paused = false,  -- the guide keeps its hands off Waypoint's arrow
    ignored = {},    -- quests you chose to leave (their item didn't drop): hidden, with what needs them
    doneByHand = {}, -- quests you marked done ("Done it"), whatever the game's record says
    lastPick = nil,  -- the zone section Automatic last chose (kept while you travel through others)
    rerun = {},      -- quests whose item didn't drop and you chose to run the dungeon again for
    ran = {},        -- ["dungeon:wing"] = true: that run (or wing) is over on the current route
}

local function Merge(dst, src)
    for k, v in pairs(src) do
        if type(v) == "table" then
            if type(dst[k]) ~= "table" then dst[k] = {} end
            Merge(dst[k], v)
        elseif dst[k] == nil then
            dst[k] = v
        end
    end
    return dst
end

function ns:Print(msg)
    DEFAULT_CHAT_FRAME:AddMessage(self.PREFIX .. ": " .. tostring(msg))
end

-- Quests or level changed: work the route out again, once, next frame.
local pending
function ns:Changed()
    if pending then return end
    pending = true
    C_Timer.After(0, function()
        pending = false
        if ns.Engine then ns.Engine:Update() end
        if ns.UI then ns.UI:Refresh() end
        if ns.MinimapButton then ns.MinimapButton:Refresh() end
    end)
end

local frame = CreateFrame("Frame")
local handlers = {}
function ns:On(event, fn)
    if not handlers[event] then
        handlers[event] = {}
        pcall(frame.RegisterEvent, frame, event)
    end
    table.insert(handlers[event], fn)
end
frame:SetScript("OnEvent", function(_, event, ...)
    for _, fn in ipairs(handlers[event] or {}) do fn(...) end
end)

function ns:OnLoad(fn)
    self.onLoad = self.onLoad or {}
    table.insert(self.onLoad, fn)
end

ns:On("ADDON_LOADED", function(name)
    if name ~= addonName then return end
    FieldGuideDB = Merge(type(FieldGuideDB) == "table" and FieldGuideDB or {}, ns.DEFAULTS)
    FieldGuideCharDB = Merge(type(FieldGuideCharDB) == "table" and FieldGuideCharDB or {}, ns.CHAR_DEFAULTS)
    ns.db, ns.char = FieldGuideDB, FieldGuideCharDB
    for _, fn in ipairs(ns.onLoad or {}) do fn() end
end)

ns:On("PLAYER_LOGIN", function()
    ns:Print("v" .. ns.VERSION .. " loaded. |cffffffff/fg|r shows or hides the guide, |cffffffff/fg help|r for more.")
end)

local function Help()
    ns:Print("/fg - show or hide the guide")
    ns:Print("/fg list - the guides and their sections")
    ns:Print("/fg guide <name> - follow the other faction's guide (/fg guide auto: yours)")
    ns:Print("/fg section <number> - follow a section (/fg section auto: the next one worth doing)")
    ns:Print("/fg settings - pick a zone's guide, and other options")
    ns:Print("/fg dungeons - dungeons in your level range with quests left (/fg dungeon <n>: guide me there, /fg dungeon stop)")
    ns:Print("/fg skip - skip the current step, /fg unskip - bring skipped steps back")
    ns:Print("/fg arrow - point Waypoint's arrow at the current step again")
    ns:Print("/fg pause, /fg resume - hide the guide and leave Waypoint's arrow alone (Play on the arrow brings it back)")
    ns:Print("/fg dock - sit under Waypoint's arrow (on), or move on your own")
    ns:Print("/fg questing - leave a dungeon's route and go back to the leveling guide")
    ns:Print("/fg questie - focus the current quest in Questie's tracker, or not")
    ns:Print("/fg lock - lock or unlock the window, /fg minimap - show or hide the minimap button")
end

SLASH_FIELDGUIDE1 = "/fieldguide"
SLASH_FIELDGUIDE2 = "/fg"
SlashCmdList.FIELDGUIDE = function(msg)
    if not ns.db then return end
    msg = strtrim(msg or "")
    local cmd, arg = msg:match("^(%S*)%s*(.-)$")
    cmd = strlower(cmd or "")
    if cmd == "" then
        ns.db.shown = not ns.db.shown
        ns:Changed()
    elseif cmd == "list" then
        ns.Engine:PrintList()
    elseif cmd == "guide" then
        ns.Engine:ChooseGuide(arg)
    elseif cmd == "section" then
        ns.Engine:ChooseSection(arg)
    elseif cmd == "dungeon" or cmd == "dungeons" then
        ns.Instance:Command(arg)
    elseif cmd == "skip" then
        ns.Engine:SkipCurrent()
    elseif cmd == "arrow" then
        ns.Engine:ResumeArrow()
    elseif cmd == "settings" or cmd == "options" or cmd == "config" then
        ns.Settings:Open()
    elseif cmd == "dock" then
        ns.db.dock = not ns.db.dock
        ns:Print(ns.db.dock and "The guide sits under Waypoint's arrow; drag either to move both."
            or "The guide moves on its own now.")
        ns.UI:Dock()
    elseif cmd == "pause" then
        ns.Engine:SetPaused(true)
    elseif cmd == "resume" then
        ns.Engine:SetPaused(false)
    elseif cmd == "questing" or cmd == "level" or cmd == "leveling" then
        if ns.char.instance then ns.Instance:Stop() else ns:Print("You're already on the leveling guide.") end
    elseif cmd == "unskip" then
        wipe(ns.char.skipped)
        wipe(ns.char.doneByHand)
        wipe(ns.char.ignored)
        ns.Engine:Invalidate()
        ns:Print("Skipped steps, and quests you marked done, are back.")
        ns:Changed()
    elseif cmd == "questie" then
        ns.db.focusQuestie = not ns.db.focusQuestie
        ns:Print(ns.db.focusQuestie and "The current quest goes to the top of Questie's tracker." or "Questie's tracker is left alone.")
    elseif cmd == "lock" then
        ns.db.locked = not ns.db.locked
        ns:Print(ns.db.locked and "Window locked." or "Window unlocked: drag it to move it.")
    elseif cmd == "minimap" then
        ns.char.minimap.hide = not ns.char.minimap.hide
        ns.MinimapButton:Refresh()
    else
        Help()
    end
end

function FieldGuide_OnCompartmentClick()
    if not ns.db then return end
    ns.db.shown = not ns.db.shown
    ns:Changed()
end
